//! insert_audio_descriptor request — ANSI/SCTE 104 2023 §9.8.11, Table 9-33
//! (opID 0x0111).
//!
//! Supplemental usage. Carries one `audio_descriptor()` entry per audio
//! component (the fields are "per SCTE 35 Table 28, audio_descriptor()"); the
//! injector adds them to the SCTE 35 section generated by the associated Normal
//! request. Transcription: `docs/ansi_scte_104/audio-and-alternate-break.md`.

use alloc::vec::Vec;

use crate::error::{Error, Result};
use crate::traits::OperationDef;
use broadcast_common::{Parse, Serialize};

/// `opID` for insert_audio_descriptor request (§8.3, Table 8-4).
pub const OP_ID: u16 = 0x0111;

/// Wire size of one audio entry (`component_tag` 1 + `ISO_code` 3 +
/// `Bit_Stream_Mode` 1 + `Num_Channels` 1 + `Full_Srvc_Audio` 1).
pub const ENTRY_LEN: usize = 7;

/// One `for (i<audio_count)` entry of Table 9-33.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize))]
pub struct AudioEntry {
    /// `component_tag` — 1 byte.
    pub component_tag: u8,
    /// `ISO_code` — 3 bytes (the ISO 639 language code of SCTE 35 Table 28).
    pub iso_code: [u8; 3],
    /// `Bit_Stream_Mode` — 1 byte.
    pub bit_stream_mode: u8,
    /// `Num_Channels` — 1 byte.
    pub num_channels: u8,
    /// `Full_Srvc_Audio` — 1 byte.
    pub full_srvc_audio: u8,
}

/// insert_audio_descriptor request — §9.8.11, Table 9-33.
///
/// `audio_count` is not a stored field: it is `entries.len()`, written through
/// `broadcast_common::len::fit_u8` on serialize.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
#[cfg_attr(feature = "serde", derive(serde::Serialize))]
pub struct InsertAudioDescriptor {
    /// The `audio_count` entries.
    pub entries: Vec<AudioEntry>,
}

impl<'a> Parse<'a> for InsertAudioDescriptor {
    type Error = Error;
    fn parse(bytes: &'a [u8]) -> Result<Self> {
        let (&count, rest) = bytes.split_first().ok_or(Error::BufferTooShort {
            need: 1,
            have: 0,
            what: "insert_audio_descriptor audio_count",
        })?;
        let need = usize::from(count) * ENTRY_LEN;
        if rest.len() < need {
            return Err(Error::BufferTooShort {
                need: 1 + need,
                have: bytes.len(),
                what: "insert_audio_descriptor entries",
            });
        }
        let entries = rest[..need]
            .chunks_exact(ENTRY_LEN)
            .map(|e| AudioEntry {
                component_tag: e[0],
                iso_code: [e[1], e[2], e[3]],
                bit_stream_mode: e[4],
                num_channels: e[5],
                full_srvc_audio: e[6],
            })
            .collect();
        Ok(Self { entries })
    }
}

impl Serialize for InsertAudioDescriptor {
    type Error = Error;
    fn serialized_len(&self) -> usize {
        1 + self.entries.len() * ENTRY_LEN
    }
    fn serialize_into(&self, buf: &mut [u8]) -> Result<usize> {
        let need = self.serialized_len();
        if buf.len() < need {
            return Err(Error::OutputBufferTooSmall {
                need,
                have: buf.len(),
            });
        }
        buf[0] = broadcast_common::len::fit_u8(
            self.entries.len(),
            "insert_audio_descriptor.audio_count",
        )?;
        for (chunk, e) in buf[1..need].chunks_exact_mut(ENTRY_LEN).zip(&self.entries) {
            chunk[0] = e.component_tag;
            chunk[1..4].copy_from_slice(&e.iso_code);
            chunk[4] = e.bit_stream_mode;
            chunk[5] = e.num_channels;
            chunk[6] = e.full_srvc_audio;
        }
        Ok(need)
    }
}

impl OperationDef<'_> for InsertAudioDescriptor {
    const OP_ID: u16 = OP_ID;
    const NAME: &'static str = "INSERT_AUDIO_DESCRIPTOR";
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample() -> InsertAudioDescriptor {
        InsertAudioDescriptor {
            entries: alloc::vec![
                AudioEntry {
                    component_tag: 0x10,
                    iso_code: *b"eng",
                    bit_stream_mode: 0,
                    num_channels: 6,
                    full_srvc_audio: 1,
                },
                AudioEntry {
                    component_tag: 0x11,
                    iso_code: *b"fra",
                    bit_stream_mode: 3,
                    num_channels: 2,
                    full_srvc_audio: 0,
                },
            ],
        }
    }

    /// Table 9-33 laid out byte by byte.
    #[test]
    fn wire_layout_matches_table_9_33() {
        let bytes = sample().try_to_bytes().unwrap();
        assert_eq!(
            bytes,
            [
                2, // audio_count
                0x10, b'e', b'n', b'g', 0, 6, 1, //
                0x11, b'f', b'r', b'a', 3, 2, 0,
            ]
        );
        assert_eq!(InsertAudioDescriptor::parse(&bytes).unwrap(), sample());
    }

    #[test]
    fn truncated_entries_are_rejected() {
        let bytes = sample().try_to_bytes().unwrap();
        assert!(InsertAudioDescriptor::parse(&bytes[..bytes.len() - 1]).is_err());
        assert!(InsertAudioDescriptor::parse(&[]).is_err());
    }

    #[test]
    fn mutate_field_changes_output() {
        let a = sample();
        let mut b = a.clone();
        b.entries[1].num_channels = 8;
        assert_ne!(a.try_to_bytes().unwrap(), b.try_to_bytes().unwrap());
    }
}
